// Synthetic geometry, NOT a TOTP QR or an enrollment secret. Format follows
// Supabase Auth -> goqrsvg 17e843f1dd40 -> SVGo 1546f124cd8b.
// A realistic module count catches the old 128k/180k size limits as well.
module.exports = function supabaseQrFixture(modules = 57) {
  const blocks = [];
  for (let y = 0; y < modules; y++) for (let x = 0; x < modules; x++) {
    blocks.push(`<rect x="${(x + 4) * 5}" y="${(y + 4) * 5}" width="5" height="5" style="fill:${(x + y) % 2 ? "black" : "white"};stroke:none"/>`);
  }
  const size = (modules + 8) * 5;
  return `<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">\n${blocks.join("\n")}\n</svg>`;
};
